import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a}from"./chunks/DIS.DdpTdGGD.js";import{_ as n,a as r}from"./chunks/M-S-LCS-AC5a.MFTz2ahv.js";import{_ as e}from"./chunks/OFF.BrU7kQE-.js";import{_ as l}from"./chunks/M-S-DS2l2.BdmWUi3X.js";import{_ as i}from"./chunks/EN.P9aPnFBv.js";import{_ as s,o as c,c as p,a3 as d}from"./chunks/framework.g9mfNVRQ.js";const D=JSON.parse('{"title":"Calibrazione avanzata","description":"","frontmatter":{"source_hash":"d8b53e5b65","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/calibrate/advancedcal.md","filePath":"it/calibrate/advancedcal.md"}'),m={name:"it/calibrate/advancedcal.md"};function u(b,o,g,v,z,h){return c(),p("div",null,[...o[0]||(o[0]=[d('<p>Questo menu contiene alcune impostazioni e meccanismi importanti per la calibrazione.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Impostazioni<br>  Impostazioni Meno Usate<br>   Calibrazione avanzata</p></div><h5 id="use-treatment-bg-values" tabindex="-1">Usa i valori di glicemia dei trattamenti <a class="header-anchor" href="#use-treatment-bg-values" aria-label="Permalink to &quot;Usa i valori di glicemia dei trattamenti {#use-treatment-bg-values}&quot;">​</a></h5><p>Puoi decidere di usare i <a href="./../use/mainUI.html#treatments">trattamenti</a> di glicemia (glicemie capillari) come calibrazioni.</p><div class="admonition xdripitem"><p class="admonition-title">Usa i valori di glicemia dei trattamenti</p><p> Scegli se calibrare con il valore di glicemia aggiunto come trattamento</p></div><div class="warning custom-block"><p class="custom-block-title">Attenzione</p><p>Usare sempre i trattamenti come calibrazioni <strong>non è consigliato</strong>.</p></div><p>La modalità automatica ti propone di usare il trattamento come calibrazione solo se xDrip rileva che le condizioni attuali sono buone per calibrare (ad esempio glicemia stabile da 20 minuti, poco rumore).</p><div class="admonition xdripitem"><p class="admonition-title">Usa i valori di glicemia dei trattamenti</p><p> Automatic mode (best)<span style="float:right;">● </span>   <br>  Ask me every time<span style="float:right;">○ </span>   <br>  Never use them<span style="float:right;">○ </span>   <br>  Always use them<span style="float:right;">○ </span>   </p></div><p>Potrebbe anche proporti di attivare la calibrazione automatica.</p><p><strong>Non è consigliato usare questa funzione con i sensori G6/G7/1/1+.</strong></p><div class="admonition xdripitem"><p class="admonition-title">Abilita la calibrazione automatica</p><p> Le glicemie capillare effettuate durante periodi stabili possono essere utilizzate automaticamente per ricalibrare dopo 20 minuti. Questo dovrebbe essere il modo più preciso per calibrare</p><p> Attivare questa funzionalità?</p><p> <span style="background-color:white;color:black;"> NO </span>    SI, ABILITA</p></div><p>Ask me every time (chiedimi ogni volta) fa esattamente questo ogni volta che inserisci un trattamento di glicemia.</p><div class="admonition xdripitem"><p class="admonition-title">Usare questa capillare per calibrare?</p><p> Vuoi usare questa glicemia capillare per calibrare?</p></div><p>Never use them (non usarli mai) non li usa mai per calibrare (e ti impedisce di trasformare un <a href="./../use/mainUI.html#treatments">trattamento</a> in una calibrazione).</p><h5 id="automatic-calibration" tabindex="-1">Calibrazione automatica <a class="header-anchor" href="#automatic-calibration" aria-label="Permalink to &quot;Calibrazione automatica {#automatic-calibration}&quot;">​</a></h5><p>Si consiglia di <strong>disattivarla con i sensori G6/G7/1/1+</strong>.</p><p>La calibrazione automatica accetta un trattamento come calibrazione se soddisfa la condizione di un andamento piatto per 20 minuti.</p><div class="admonition xdripitem"><p class="admonition-title">Calibrazione automatica <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Calibra automaticamente utilizzando le letture di glicemia se le condizioni sembrano giuste, senza chiedere conferma (sperimentale)</p></div><h3 id="plugins" tabindex="-1">Plugin <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugin {#plugins}&quot;">​</a></h3><p>In xDrip sono disponibili dei plugin di calibrazione, ma la maggior parte non viene più usata. Se attivato, un plugin agisce al posto della calibrazione standard di xDrip. L&#39;idea era di offrire una scelta personalizzabile dell&#39;algoritmo di calibrazione, ma non è mai stata implementata del tutto. In generale, per ragioni di sicurezza, un sensore che ha bisogno di un plugin per essere calibrato andrebbe sostituito.</p><div class="warning custom-block"><p class="custom-block-title"><strong>SICUREZZA</strong></p><p><strong>I meccanismi di sicurezza della calibrazione non si applicano ai plugin. Usare un plugin per aggirare un errore di calibrazione è pericoloso.</strong></p></div><div class="admonition xdripitem"><p class="admonition-title">Plugin di calibrazione</p><p> Plugin di calibrazione secondaria sperimentale</p></div><div class="warning custom-block"><p class="custom-block-title">Estensione Wear</p><p>I plugin non sono implementati del tutto in Wear. Potresti vedere valori diversi sullo smartwatch.</p></div><div class="admonition xdripitem"><p class="admonition-title">Plugin di calibrazione</p><p> None<br>  Datricsae - pronounced: da-trix-ee - highly experimental<br>  Fixed Slope Example - never use for real data<br>  xDrip Original - classic algorithm<br>  Last7Ua - Unweighted last 7 calibrations. Example only</p></div><p><strong><code>None</code></strong>: per impostazione predefinita viene usato l&#39;algoritmo di xDrip. <strong>Consigliato</strong></p><p><strong><code>Datricsae</code></strong> era molto usato da chi aveva problemi con l&#39;algoritmo predefinito di xDrip. Richiede 8 punti di calibrazione (se sono meno di 4 viene usato l&#39;algoritmo originale di xDrip) e ha limiti di pendenza tra 0,5 e 1,7. Il suo punto di forza principale è eliminare i valori anomali (punti di calibrazione sbagliati) che cadono troppo lontano dalla retta di calibrazione. Dopo il filtraggio, se il numero di punti di calibrazione scende sotto 4 o la pendenza è fuori dai limiti, viene usato l&#39;algoritmo classico di xDrip.<br> Fai attenzione: calibrazioni rumorose possono portare a risultati incoerenti.</p><img src="'+n+'" style="zoom:75%;"><p><strong><code>Fixed slope</code></strong> è un plugin vuoto che restituisce una pendenza di 1,08 e un&#39;intercetta di -5. <strong>Non usarlo per la glicemia reale.</strong></p><p><strong><code>xDrip Original</code></strong> era l&#39;equivalente in forma di plugin dell&#39;algoritmo di xDrip. Non fa nulla di diverso dall&#39;algoritmo di xDrip. <strong>Usarlo non porta alcun vantaggio.</strong></p><p><strong><code>Last 7 unweighted</code></strong> è stato un primo tentativo di migliorare l&#39;algoritmo originale. Richiede almeno 4 calibrazioni (usa al massimo le ultime 7; sotto le 4 viene usato l&#39;algoritmo attuale di xDrip). <strong>Non consigliato.</strong></p><div class="admonition xdripitem"><p class="admonition-title">Grafico dei valori Plugin <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Mostra i risultati della glicemia dal plugin sul grafico principale</p></div><p>Attivalo se vuoi che xDrip tracci i risultati ottenuti con il plugin.</p><img src="'+l+'" style="zoom:75%;"><div class="admonition xdripitem"><p class="admonition-title">Usa un Plugin Glucosio <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> La visualizzazione del valore di glicemia principale proviene dal plugin!</p></div><p>Attivalo se vuoi che il valore principale della glicemia provenga dai risultati del plugin. Comparirà una P cerchiata.</p><img src="'+r+'" style="zoom:75%;"><div class="admonition xdripitem"><p class="admonition-title">Ignorare TUTTI i Plugin <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Tutti i nuovi dati della glicemia saranno calcolati e salvati dal Plugin selezionato e non dall&#39;algoritmo standard xDrip. Questo non è stato testato e potrebbe essere impreciso e includere bug. Usare con estrema cautela.</p></div><p>Non implementato.</p><h3 id="calibrations" tabindex="-1">Calibrazioni <a class="header-anchor" href="#calibrations" aria-label="Permalink to &quot;Calibrazioni {#calibrations}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Calibrazione doppia <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Richiedi una seconda calibrazione capillare iniziale facoltativa</p></div><p>Se per la calibrazione iniziale non esegui davvero due glicemie capillari distinte, disattivala.</p><p>La Modalità di calibrazione Vecchia Scuola ripristina l&#39;intervallo originale, più stretto, di pendenze consentite nell&#39;algoritmo di calibrazione classico di xDrip (prima del 2017), rendendo più probabili le pendenze predefinite. È visibile solo con la Modalità Sviluppatore attivata.</p><div class="admonition xdripitem"><p class="admonition-title">Modalità di calibrazione Vecchia Scuola <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Intervallo originale (più stretto) di fattori consentiti nell&#39;algoritmo di calibrazione classico xDrip (pre-2017). Preferire quelli predefiniti perché più probabili! (solo modalità ingegneristica)</p></div><div class="admonition xdripitem"><p class="admonition-title">Calibrazioni poco frequente <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Se necessario, usa calibrazioni più vecchie, es.: se le calibrazioni vengono fatte raramente.</p></div><p>Le calibrazioni troppo vecchie vengono ignorate: se calibri raramente e vuoi che le misure di calibrazione più vecchie pesino sulla curva di calibrazione attuale, attiva questa opzione.</p><h3 id="libre-specific" tabindex="-1">Specifico per Libre <a class="header-anchor" href="#libre-specific" aria-label="Permalink to &quot;Specifico per Libre {#libre-specific}&quot;">​</a></h3><h5 id="non-fixed-libre-slopes" tabindex="-1">Calibrazione non linear per Libre <a class="header-anchor" href="#non-fixed-libre-slopes" aria-label="Permalink to &quot;Calibrazione non linear per Libre {#non-fixed-libre-slopes}&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Calibrazione non linear per Libre <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Abilitare per permettere la calibrazione non lineare (pendenze variabile) per il sensore Libre</p></div><p>I sensori Libre possono essere difficili da calibrare. Se non riesci a ottenere precisione su tutto l&#39;intervallo o non calibri mai nell&#39;intervallo alto, disattiva questa opzione e rendi la pendenza uguale a 1. È consigliato ai principianti.</p><p><strong>Per sicurezza, calibra sempre con glicemia stabile nella parte bassa dell&#39;intervallo normale.</strong></p><div class="admonition xdripitem"><p class="admonition-title">Check Libre Serial <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Automatically stop if Libre Serial changes unexpectedly</p></div><p>Trasferire le calibrazioni dal vecchio sensore a quello nuovo è pericoloso. <strong>Lascia questa opzione attivata.</strong></p><h3 id="bypass-quality-check" tabindex="-1">Ignora il controllo di qualità <a class="header-anchor" href="#bypass-quality-check" aria-label="Permalink to &quot;Ignora il controllo di qualità {#bypass-quality-check}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Ignora il controllo di qualità <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Consenti la calibrazione iniziale anche se non disponiamo di dati abbastanza validi. Attenzione potrebbe causare una calibrazione imprecisa!</p></div><p>Durante le misure preliminari per la prima calibrazione sono necessarie 3 misure valide. Se mancano o non rispettano i valori di sicurezza, xDrip attende. Attivando questa opzione la calibrazione è consentita senza controllo. <strong>Non consigliato.</strong></p><div class="admonition xdripitem"><p class="admonition-title">Sto raccogliendo le prime letture</p><p> ✔ Raccolta dati in esecuzione<br>  ✔ Ricezione dati dal collector MiaoMiao<br>  ✔ Ho ricevuto alcuni dati recenti<br>  ⧖ Ho ricevuto abbastanza dati per calibrare<br>  <strong>Need 3 recent readings, got only 1 so far</strong><br>  Next reading expected in 1 minute</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',58)])])}const S=s(m,[["render",u]]);export{D as __pageData,S as default};
